import fs from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

import type { ExperimentSummary } from "@/lib/types";
import { EXAMPLE_ORDER, getBundle } from "./build";

/**
 * The mock experiments are generated by the mock harness (`build.ts`), which takes a few
 * seconds, so the app loads the pre-generated JSON in `generated/` instead. This test checks
 * that the committed files still match a fresh build, and rewrites them with
 *
 *     UPDATE_MOCKS=1 npx vitest run src/lib/mocks
 */

const dir = path.join(__dirname, "generated");
const update = process.env.UPDATE_MOCKS === "1";

function compact(value: unknown): string {
  return JSON.stringify(value, (_k, v) => (typeof v === "number" ? Number(v.toPrecision(7)) : v));
}

function approxEqual(a: unknown, b: unknown, path = "$"): string | null {
  if (typeof a === "number" && typeof b === "number") {
    const tol = 1e-3 * Math.max(1, Math.abs(a), Math.abs(b));
    return Math.abs(a - b) <= tol ? null : `${path}: ${a} vs ${b}`;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return `${path}: length ${a.length} vs ${b.length}`;
    for (let i = 0; i < a.length; i++) {
      const r = approxEqual(a[i], b[i], `${path}[${i}]`);
      if (r) return r;
    }
    return null;
  }
  if (a && b && typeof a === "object" && typeof b === "object") {
    const ka = Object.keys(a as object).filter((k) => (a as Record<string, unknown>)[k] !== undefined);
    const kb = Object.keys(b as object).filter((k) => (b as Record<string, unknown>)[k] !== undefined);
    if (ka.join() !== kb.join()) return `${path}: keys ${ka.join()} vs ${kb.join()}`;
    for (const k of ka) {
      const r = approxEqual((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k], `${path}.${k}`);
      if (r) return r;
    }
    return null;
  }
  return a === b ? null : `${path}: ${String(a)} vs ${String(b)}`;
}

describe("mock experiments", () => {
  it("the committed JSON matches a fresh build", { timeout: 120_000 }, () => {
    const summaries: ExperimentSummary[] = [];
    for (const id of EXAMPLE_ORDER) {
      const bundle = getBundle(id)!;
      const file = path.join(dir, `${id}.json`);
      if (update) {
        fs.mkdirSync(dir, { recursive: true });
        fs.writeFileSync(file, compact(bundle) + "\n");
      }
      const committed = JSON.parse(fs.readFileSync(file, "utf8"));
      const fresh = JSON.parse(compact(bundle));
      expect(approxEqual(committed, fresh), `${id} is stale; run UPDATE_MOCKS=1`).toBeNull();
      const e = bundle.experiment;
      summaries.push({
        id: e.id, title: e.title, system_type: e.system_type, status: e.status, created_at: e.created_at,
        is_example: e.is_example, confidence: e.confidence, review_status: e.review_status, headline: e.headline,
        winner_name: e.winner_name, thumbnail_url: e.thumbnail_url, blurb: e.blurb,
      });
    }
    const indexFile = path.join(dir, "index.json");
    if (update) fs.writeFileSync(indexFile, compact(summaries) + "\n");
    expect(approxEqual(JSON.parse(fs.readFileSync(indexFile, "utf8")), JSON.parse(compact(summaries)))).toBeNull();
  });

  it("tells the intended stories", () => {
    const spin = getBundle("ex-spin-down")!.experiment;
    expect(spin.conclusion!.winner_id).toBe("S2");
    const s0 = spin.models.find((m) => m.id === "S0")!;
    expect(s0.prior_rank).toBe(1); // Wonder's first guess ...
    expect(s0.status).toBe("rejected"); // ... was refuted on held-out frames
    expect(s0.rejection_reason).toContain("Held-out RMSE");
    expect(spin.conclusion!.confidence).toBe("high");

    const pend = getBundle("ex-pendulum")!.experiment;
    expect(pend.conclusion!.winner_id).toBe("P1");
    expect(pend.models.find((m) => m.id === "P0")!.status).toBe("rejected");
    expect(pend.conclusion!.confidence).toBe("medium");
    const [v1, v2] = pend.ghosts;
    expect(v1.divergence_onset_s).not.toBeNull();
    expect(v2.max_error_mm).toBeLessThan(v1.max_error_mm);

    const fall = getBundle("ex-free-fall")!.experiment;
    expect(fall.conclusion!.winner_id).toBe("FF0");
    expect(fall.ghosts[0].divergence_onset_s).toBeNull();

    const cant = getBundle("ex-cant-tell")!.experiment;
    expect(cant.conclusion!.confidence).toBe("low");
    expect(cant.conclusion!.cant_tell!.fixes.length).toBeGreaterThan(1);
    expect(cant.review!.status).toBe("contested");
  });
});
